{
  "explanation": "Plan A costs C = 20 + 0.10m and Plan B costs C = 35 + 0.05m. Setting them equal gives 20 + 0.10m = 35 + 0.05m, so 0.05m = 15 and m = 300 minutes. At that point both plans cost $50. The graph shows the two cost lines crossing at the break-even point.",
  "manimCode": "const ax = new Axes({
  xRange: [0, 600, 100],
  yRange: [0, 80, 10],
  xLength: 10,
  yLength: 5.5,
  tips: true
});
ax.shift([-0.5, -0.3, 0]);

const xLabel = new Text({ text: 'Minutes', fontSize: 22, color: GRAY });
xLabel.nextTo(ax, DOWN);
xLabel.shift([0, 0.15, 0]);
const yLabel = new Text({ text: 'Cost ($)', fontSize: 22, color: GRAY });
yLabel.nextTo(ax, LEFT);
yLabel.shift([0.3, 0, 0]);

const lineA = ax.plot(m => 20 + 0.10 * m, { color: BLUE, xRange: [0, 600] });
const lineB = ax.plot(m => 35 + 0.05 * m, { color: ORANGE, xRange: [0, 600] });

const intersectDot = new Dot({ point: ax.c2p(300, 50), color: YELLOW, radius: 0.12 });

const labelA = new Text({ text: 'A: 20 + 0.10m', fontSize: 20, color: BLUE });
labelA.moveTo(ax.c2p(480, 72));
const labelB = new Text({ text: 'B: 35 + 0.05m', fontSize: 20, color: ORANGE });
labelB.moveTo(ax.c2p(480, 55));

const eqLabel = new MathTex({ latex: 'm = 300 \\quad C = \\$50' });
await eqLabel.waitForRender();
eqLabel.moveTo([0, 3.2, 0]);
eqLabel.setColor(YELLOW);

const title = new Text({ text: 'Break-even: when do the plans cost the same?', fontSize: 26, color: WHITE });
title.moveTo([0, 3.7, 0]);

scene.add(ax, xLabel, yLabel, lineA, lineB, intersectDot, labelA, labelB, eqLabel, title);

// Vertical & horizontal guide lines at intersection
const vGuide = new Polygon({
  vertices: [ax.c2p(300, 0), ax.c2p(300, 50)],
  color: YELLOW,
  strokeWidth: 2
});
vGuide.setFillOpacity(0);
const hGuide = new Polygon({
  vertices: [ax.c2p(0, 50), ax.c2p(300, 50)],
  color: YELLOW,
  strokeWidth: 2
});
hGuide.setFillOpacity(0);
scene.add(vGuide, hGuide);

// Interactive slider to explore cost at any minute count
let currentM = 300;
let costDotA = new Dot({ point: ax.c2p(300, 50), color: BLUE, radius: 0.1 });
let costDotB = new Dot({ point: ax.c2p(300, 50), color: ORANGE, radius: 0.1 });
scene.add(costDotA, costDotB);

let infoText = new Text({ text: 'At 300 min: A=$50  B=$50', fontSize: 22, color: WHITE });
infoText.moveTo([0, -3.5, 0]);
scene.add(infoText);

function updateInfo(m) {
  currentM = m;
  const cA = 20 + 0.10 * m;
  const cB = 35 + 0.05 * m;
  costDotA.moveTo(ax.c2p(m, cA));
  costDotB.moveTo(ax.c2p(m, cB));
  const pos = infoText.getCenter();
  scene.remove(infoText);
  const cheaper = cA < cB ? 'A cheaper' : cB < cA ? 'B cheaper' : 'SAME cost';
  infoText = new Text({
    text: `At ${Math.round(m)} min: A=$${cA.toFixed(2)}  B=$${cB.toFixed(2)}  (${cheaper})`,
    fontSize: 22,
    color: WHITE
  });
  infoText.moveTo(pos);
  scene.add(infoText);
}

const controls = new Controls(scene, { position: 'top-right', width: 260 });
controls.addSlider({
  label: 'Minutes',
  min: 0,
  max: 600,
  value: 300,
  step: 10,
  onChange: (val) => updateInfo(val)
});
controls.addButton({
  label: 'Reset to break-even',
  onClick: () => {
    updateInfo(300);
  }
});

await scene.wait(999999);"
